//! Black-box end-to-end tests: spawn the built binary and speak real MCP over
//! stdio. No internal APIs are used, so these exercise exactly what a client
//! gets — schema shapes, error semantics, blob handles and all.
//!
//! The contract scenarios (handshake, cursor completeness, blob integrity,
//! error semantics, boot behaviour, determinism) come from
//! `u2s-render-test-harness` and are shared with the XFA server; what remains
//! here is genuinely PDF-specific.

use std::path::{Path, PathBuf};

use harness::{ErrorCase, ServerUnderTest, call, error_text, image_blocks, structured};
use serde_json::json;
use u2s_render_test_harness as harness;

/// Fixtures are generated by the library crate's test suite; running it first
/// is what puts them on disk.
fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../u2s-render-pdf/fixtures/generated")
        .canonicalize()
        .expect("fixtures missing — run `cargo test -p u2s-render-pdf` first to generate them")
}

fn fixture(name: &str) -> String {
    fixtures().join(name).display().to_string()
}

fn blob_dir() -> PathBuf {
    let dir = std::env::temp_dir().join("u2s-e2e-blobs");
    std::fs::create_dir_all(&dir).expect("blob dir");
    dir
}

/// The server under test, with limits chosen so both the inline and blob paths
/// are reachable from the fixtures: a 72 dpi page stays inline, 300 dpi does not.
fn server() -> ServerUnderTest {
    ServerUnderTest::locate("u2s-render-pdf-mcp", "pdf")
        .env("U2S_BLOB_DIR", blob_dir().display().to_string())
        .env("MAX_INLINE_BYTES", "60000")
}

async fn client() -> harness::Client {
    server().connect().await
}

// ------------------------------------------------- shared contract battery

#[tokio::test]
async fn handshake_and_manifest_agree() {
    harness::handshake_matches_manifest(&server(), &fixtures()).await;
}

#[tokio::test]
async fn cursor_walk_covers_a_large_document_exactly_once() {
    // A byte budget low enough that it binds before the count cap on these
    // small pages, so the walk exercises both stopping conditions.
    let server = server().env("MAX_RESPONSE_BYTES", "6000");
    let budget_stops = harness::cursor_walk_complete(
        &server,
        &fixture("many-pages.pdf"),
        250,
        4,
        json!({"dpi": 36}),
    )
    .await;
    assert!(
        budget_stops > 0,
        "the byte budget should have bound at least once over 250 pages"
    );
}

#[tokio::test]
async fn an_oversized_image_becomes_a_blob_handle_on_disk() {
    harness::blob_digest_valid(&server(), &fixture("ten-pages.pdf"), 300).await;
}

#[tokio::test]
async fn failures_are_tool_errors_and_the_session_survives() {
    let cases = vec![
        ErrorCase::new(
            "pdf_render_page",
            json!({ "doc_path": fixture("ten-pages.pdf"), "page": 15 }),
            &["15", "1..10"],
        ),
        ErrorCase::new(
            "pdf_info",
            json!({ "doc_path": "/nope/missing.pdf" }),
            &["/nope/missing.pdf"],
        ),
        ErrorCase::new(
            "pdf_info",
            json!({ "doc_path": fixture("encrypted.pdf") }),
            &["password-protected"],
        ),
        ErrorCase::new(
            "pdf_info",
            json!({ "doc_path": fixture("truncated.pdf") }),
            &[],
        ),
        ErrorCase::new(
            "pdf_info",
            json!({ "doc_path": fixture("not-a-pdf.txt") }),
            &[],
        ),
        ErrorCase::new(
            "pdf_render_page",
            json!({ "doc_path": fixture("ten-pages.pdf") }),
            &["page"],
        ),
        ErrorCase::new(
            "pdf_render_region",
            json!({
                "doc_path": fixture("ten-pages.pdf"), "page": 1,
                "rect_pt": { "x": 5000, "y": 5000, "width": 100, "height": 100 }
            }),
            &["outside page"],
        ),
        // A caller's bad query is named as an argument fault, not as a pdfium
        // failure — the reason `InvalidArgument` is its own variant.
        ErrorCase::new(
            "pdf_search_text",
            json!({ "doc_path": fixture("unicode-text.pdf"), "query": "(unclosed", "regex": true }),
            &["query", "invalid regex"],
        ),
        ErrorCase::new(
            "pdf_search_text",
            json!({ "doc_path": fixture("unicode-text.pdf"), "query": "" }),
            &["query", "empty string"],
        ),
        ErrorCase::new(
            "pdf_search_text",
            json!({ "doc_path": fixture("ten-pages.pdf"), "query": "Page", "from": 99 }),
            &["99", "1..10"],
        ),
        ErrorCase::new(
            "pdf_search_text",
            json!({ "doc_path": fixture("unicode-text.pdf") }),
            &["query"],
        ),
    ];
    harness::errors_are_tool_errors(
        &server(),
        &cases,
        (
            "pdf_info".to_string(),
            json!({ "doc_path": fixture("ten-pages.pdf") }),
        ),
    )
    .await;
}

#[test]
fn the_server_refuses_to_start_without_pdfium() {
    // PDFIUM_LIB_PATH is authoritative, so this must fail rather than falling
    // back to the vendored library.
    harness::boot_failure_contract(
        &server(),
        &[("PDFIUM_LIB_PATH", "/definitely/not/here")],
        &["fetch-pdfium.sh"],
    );
}

#[tokio::test]
async fn the_same_render_is_identical_across_processes() {
    harness::cross_process_determinism(
        &server(),
        json!({ "doc_path": fixture("ten-pages.pdf"), "page": 1, "dpi": 72, "format": "png" }),
        "pdf_render_page",
    )
    .await;
}

// ------------------------------------------------------ PDF-specific tests

#[tokio::test]
async fn info_then_render_returns_an_inline_image() {
    let c = client().await;

    let info = call(
        &c,
        "pdf_info",
        json!({ "doc_path": fixture("ten-pages.pdf") }),
    )
    .await;
    let s = structured(&info);
    assert_eq!(s["page_count"], 10);
    assert_eq!(s["form_type"], "none");
    assert_eq!(s["pages"].as_array().unwrap().len(), 10);

    let render = call(
        &c,
        "pdf_render_page",
        json!({ "doc_path": fixture("ten-pages.pdf"), "page": 1, "dpi": 72 }),
    )
    .await;
    assert_eq!(image_blocks(&render), 1, "expected one inline image");
    let s = structured(&render);
    assert_eq!(s["page"], 1);
    assert_eq!(s["inline"], true);
    assert!((s["width_px"].as_f64().unwrap() - 595.0).abs() <= 2.0);

    c.cancel().await.ok();
}

#[tokio::test]
async fn an_explicit_page_list_is_honoured_in_order() {
    let c = client().await;
    let batch = call(
        &c,
        "pdf_render_pages",
        json!({ "doc_path": fixture("ten-pages.pdf"), "pages": [8, 3, 5], "dpi": 36 }),
    )
    .await;
    assert_eq!(structured(&batch)["rendered"], json!([8, 3, 5]));
    c.cancel().await.ok();
}

#[tokio::test]
async fn region_zoom_crops_to_the_requested_rect() {
    let c = client().await;
    let res = call(
        &c,
        "pdf_render_region",
        json!({
            "doc_path": fixture("ten-pages.pdf"), "page": 1,
            "rect_pt": { "x": 50, "y": 50, "width": 200, "height": 100 },
            "dpi": 144, "format": "png"
        }),
    )
    .await;
    let s = structured(&res);
    assert!(
        (s["width_px"].as_f64().unwrap() - 400.0).abs() <= 3.0,
        "{s}"
    );
    assert!(
        (s["height_px"].as_f64().unwrap() - 200.0).abs() <= 3.0,
        "{s}"
    );
    c.cancel().await.ok();
}

#[tokio::test]
async fn page_text_reports_windowing_honestly() {
    let c = client().await;

    let full = call(
        &c,
        "pdf_page_text",
        json!({ "doc_path": fixture("unicode-text.pdf"), "page": 1, "limit": 100000 }),
    )
    .await;
    let fs = structured(&full);
    assert_eq!(fs["truncated"], false);
    let total = fs["total_chars"].as_u64().unwrap();
    assert!(total > 0);

    let window = call(
        &c,
        "pdf_page_text",
        json!({ "doc_path": fixture("unicode-text.pdf"), "page": 1, "limit": 5 }),
    )
    .await;
    let ws = structured(&window);
    assert_eq!(ws["truncated"], true, "a short window must say it is short");
    assert_eq!(
        ws["total_chars"], total,
        "total is of the page, not the window"
    );

    c.cancel().await.ok();
}

/// pdfium renders an XFA document's shim page, which *looks* like success —
/// the warning is the only thing standing between a caller and a wrong answer.
#[tokio::test]
async fn an_xfa_document_carries_a_routing_warning() {
    let xfa = u2s_test_assets::corpus_form("AAAA_019_DE.pdf");
    let c = client().await;
    let path = xfa.display().to_string();

    let info = call(&c, "pdf_info", json!({ "doc_path": path })).await;
    let s = structured(&info);
    assert!(
        s["form_type"] == "xfa_full" || s["form_type"] == "xfa_foreground",
        "expected an XFA form type, got {}",
        s["form_type"]
    );
    let warning = s["warning"].as_str().expect("XFA info must warn");
    assert!(warning.contains("XFA renderer"), "{warning}");

    let render = call(
        &c,
        "pdf_render_page",
        json!({ "doc_path": path, "page": 1, "dpi": 72 }),
    )
    .await;
    assert_ne!(render.is_error, Some(true), "{}", error_text(&render));
    assert!(
        structured(&render)["warning"].is_string(),
        "the render must carry the routing warning too"
    );

    c.cancel().await.ok();
}

// ------------------------------------------------------- shared search battery

/// The search contract: a hit addresses itself in `pdf_page_text`.
#[tokio::test]
async fn a_search_hit_addresses_itself_in_page_text() {
    harness::search_hit_addresses_itself(
        &server(),
        &fixture("unicode-text.pdf"),
        "Zuerich",
        "Zuerich",
        json!({}),
    )
    .await;
}

/// The search cursor covers a 250-page document exactly once. `SEARCH_MAX_PAGES`
/// is set low so the cursor is genuinely exercised rather than the whole
/// document coming back in one call.
#[tokio::test]
async fn the_search_cursor_covers_a_large_document_exactly_once() {
    let server = server().env("SEARCH_MAX_PAGES", "40");
    harness::search_cursor_walk_complete(
        &server,
        &fixture("many-pages.pdf"),
        250,
        "Page",
        json!({}),
    )
    .await;
}

/// Case-insensitive by default for a literal, and the offset addresses the
/// document's own text rather than a case-folded copy of it.
#[tokio::test]
async fn a_literal_search_is_case_insensitive() {
    let c = client().await;
    let r = call(
        &c,
        "pdf_search_text",
        json!({ "doc_path": fixture("unicode-text.pdf"), "query": "hello WORLD" }),
    )
    .await;
    let s = structured(&r);
    assert_eq!(s["total_matches"], 1);
    assert!(
        s["matches"][0]["context"]
            .as_str()
            .unwrap_or("")
            .contains("Hello world"),
        "the document's own case must come back: {s}"
    );
    c.cancel().await.ok();
}
